import { definePlugin, action, job, route, text, integer, db } from "zero";
export default (options: { suffix: string }) => definePlugin({
  name: "seo",
  hooks: { posts: { beforeCreate(data) { return { ...data, summary: data.title + options.suffix }; } } },
  actions: { tag: action({ input: { t: text().notNull() }, access: "editor", handler({ t }) { return t + options.suffix; } }) },
  jobs: { warm: job({ input: { id: integer().notNull() }, handler() {} }) },
  routes: { sitemap: route({ method: "GET", path: "/sitemap-seo.xml", access: "anyone", async handler() {
    const rows = await db.query.posts.findMany({ limit: 5 });
    return { headers: { "content-type": "application/xml" }, body: `<urlset>${rows.length}</urlset>` };
  } }) },
});
